#!/bin/sh
set -eu
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
APP="$ROOT/adhook/app/src/main"
HTML="$APP/assets/webroot/index.html"
FILEEDIT="$ROOT/fx-module/scripts/fileedit.sh"
APPLY="$ROOT/fx-module/scripts/apply.sh"
UTIL="$ROOT/fx-module/scripts/util.sh"
fail(){ echo "FAIL: $*" >&2; exit 1; }

[ -s "$HTML" ] || fail "complete FX WebUI was not staged into APK assets"
grep -q "FX: merged pageAd into pageHosts" "$HTML" || fail "legacy Ad content was not merged into the Hosts page"
grep -q "mitmTrafficEnable" "$HTML" || fail "merged Ad certificate/MITM controls are missing"
grep -q 'data-tab="ad"' "$HTML" || fail "agreed Ad navigation entry is missing"
! grep -Fq 'while(rulesPage.firstChild)adPage.appendChild(rulesPage.firstChild)' "$HTML" || fail "runtime still reverses the Ad-to-Hosts migration"
! grep -Fq 'rulesPage.remove()' "$HTML" || fail "runtime still deletes the canonical Hosts page"
! grep -q 'data-tab="hosts"' "$HTML" || fail "merged Hosts content must not create a duplicate Hosts tab"
grep -q "pageHosts.*classList.toggle('on',t==='ad')" "$HTML" || fail "Ad tab does not activate the merged Hosts content"
grep -Fq 'rulesPage.insertBefore(overview,rulesPage.firstChild)' "$HTML" || fail "rule overview was moved into the obsolete Ad page"
! grep -q "pageAd.*classList.toggle('on',t==='ad')" "$HTML" || fail "legacy Ad page is still activated as a separate tab"
grep -q "hostsOpenEditor" "$HTML" || fail "local system Hosts editor is missing from the merged page"
[ -s "$FILEEDIT" ] || fail "privileged paged file editor backend missing"
[ -s "$APPLY" ] || fail "hosts apply pipeline missing"
[ -s "$UTIL" ] || fail "hosts transaction/mount utility missing"
grep -Fq 'base="$PG/local/hosts"; ov=""; name="hosts"' "$FILEEDIT" || fail "editable local hosts must be a separate extensionless source"
grep -Fq 'base="/system/etc/hosts"; ov=""; name="hosts"' "$FILEEDIT" || fail "live system hosts view must read the actual Android hosts path"
grep -Fq 'sub:*|system-hosts)' "$FILEEDIT" || fail "subscription cache and live system hosts must remain read-only"
grep -Fq 'edit|ins|del|put|replacepage|reset|import-external' "$FILEEDIT" || fail "read-only file sources expose write operations"
grep -Fq 'write_tmp_to()' "$FILEEDIT" || fail "paged editor writes must use the transactional writer"
grep -Fq 'cmp -s' "$FILEEDIT" || fail "paged editor must verify staged and backup file copies"
grep -Fq '$_w_dst.bak' "$FILEEDIT" || fail "paged editor must retain a verified rollback backup"
grep -Fq 'pg_log "hosts: merged $_hfl_count lines from local/hosts"' "$APPLY" || fail "local hosts source is not merged into the effective hosts build"
grep -Fq 'pg_commit_hosts_candidate "$TMP"' "$APPLY" || fail "effective hosts replacement must use the transaction helper"
grep -Fq 'mount --bind "$PG/hosts" /system/etc/hosts' "$APPLY" || fail "effective hosts output is not bound to Android system hosts"
grep -Fq 'pg_hosts_mount_state' "$UTIL" || fail "hosts mount ownership must be checked before replacement"
sh -n "$FILEEDIT" || fail "file editor backend shell syntax invalid"
sh -n "$APPLY" || fail "hosts apply shell syntax invalid"
[ "$(wc -c < "$HTML" | tr -d ' ')" -gt 500000 ] || fail "FX WebUI asset is unexpectedly truncated"
for page in pageVpn pageAd pageHosts pagePrivacy pageScript pageMore; do
  grep -q "id=\"$page\"" "$HTML" || fail "missing migrated UI page: $page"
done
for panel in vpnPanel rootPanel advPanel netPanel permPanel sensorPanel locationPanel devicePanel mediaPanel filePanel notifyPanel kernelPanel miscPanel crashPanel stylePanel langPanel; do
  grep -q "id=\"$panel\"" "$HTML" || fail "missing migrated settings panel: $panel"
done
for marker in fxHookAppList fxHookSync builtinCerts mitmTrafficEnable hostsOpenEditor vpnSubUpdateAll; do
  grep -q "$marker" "$HTML" || fail "missing migrated feature marker: $marker"
done

ACTIVITY="$APP/java/de/privacyguard/adhook/MainActivity.java"
BRIDGE="$APP/java/de/privacyguard/adhook/RootBridge.java"
HOOK="$APP/java/de/privacyguard/adhook/AdVisibilityHook.java"
PARSER="$APP/java/de/privacyguard/adhook/UnifiedHookConfigParser.java"
PARSER_TEST="$ROOT/adhook/app/src/test/java/de/privacyguard/adhook/UnifiedHookConfigParserTest.java"
ROOT_ACCESS="$APP/java/de/privacyguard/adhook/RootAccess.java"
GENERATOR="$ROOT/fx-module/scripts/gen_xposed_conf.sh"
LEGACY_HOOK="$APP/java/de/privacyguard/hook/MainHook.java"
MERGE_HOOK="$ROOT/fx-patches/merge_hook_single_apk.py"
[ -s "$ACTIVITY" ] || fail "MainActivity missing"
[ -s "$BRIDGE" ] || fail "RootBridge missing"
[ -s "$ROOT_ACCESS" ] || fail "RootAccess missing"
grep -Fq 'section("KernelSU / Root")' "$ACTIVITY" || fail "Hook authorization hub must expose Root status"
grep -Fq 'checkRoot(rootState, false);' "$ACTIVITY" || fail "Hook authorization hub must query actual Root UID and FX module state"
grep -Fq 'refreshRoot.setOnClickListener(v -> checkRoot(rootState, false))' "$ACTIVITY" || fail "Root refresh button must re-run the Root status check"
[ -s "$LEGACY_HOOK" ] || fail "copied full legacy Hook entrypoint missing"
! grep -Eqi 'AdVisibility|AdView|ad_view|ads_splash|ads_feed|ads_overlay|installAdView' "$LEGACY_HOOK" || fail "legacy API-82 entrypoint must not install duplicate visual Ad hooks"
grep -Fq 'installAdViewHooks' "$HOOK" || fail "modern API-101 entrypoint must own visual Ad interception"
grep -Fq 'API101_MANAGED_PATH' "$LEGACY_HOOK" || fail "legacy Hook does not read the API-101 ownership map"
grep -Fq 'loadApi101Managed();' "$LEGACY_HOOK" || fail "legacy Hook does not load per-package duplicate-suppression flags"
grep -Fq 'private boolean loadConf() {' "$LEGACY_HOOK" || fail "legacy config loader declaration missing"
sed -n '/private boolean loadConf() {/,/^    }/p' "$LEGACY_HOOK" | grep -Fq 'loadApi101Managed();' || fail "ownership map must load at the start of legacy loadConf before early returns"
grep -Fq 'api101Managed.contains(pkg + "|" + k)' "$LEGACY_HOOK" || fail "legacy Hook does not suppress migrated duplicate features"
grep -Fq 'DISABLED_EVASION_KEYS.contains(k)' "$LEGACY_HOOK" || fail "legacy evasion denylist was lost during merge"
grep -Fq 'legacyDuplicateKeys' "$ACTIVITY" || fail "native Hook publisher does not map migrated API-101 features to legacy duplicate keys"
for feature in exif_strip mic_silence notification_listen_block notification_permission_hide sensor_accel sensor_gyro sensor_light sensor_magnet sensor_pressure sensor_prox sensor_rate_limit; do
  grep -Fq "\"$feature\"" "$ACTIVITY" || fail "native per-app Hook UI is missing supported feature: $feature"
done
keys_block=$(sed -n '/String\[\] keys=/,/};/p' "$ACTIVITY")
for feature in privacy exif_strip clipboard_read_block clipboard_isolate wifi_scan_block notification_listen_block notification_permission_hide mic_silence camera_access_block location_access_block mic_access_block media_store_query_block sensor_accel sensor_gyro sensor_light sensor_magnet sensor_pressure sensor_prox sensor_rate_limit member_diag; do
  printf '%s' "$keys_block" | grep -Fq "\"$feature\"" || fail "native publisher does not serialize Hook feature: $feature"
done
grep -Fq '{"mic_silence","mic_block"}' "$ACTIVITY" || fail "API-101 microphone silence must suppress the legacy mic_block read hook"
grep -Fq '{"mic_silence","audio_fp_block"}' "$ACTIVITY" || fail "API-101 microphone silence must suppress legacy audio perturbation"
for legacy_key in exif_strip clipboard clipboard_isolate sensor_accel sensor_gyro sensor_light sensor_magnet sensor_pressure sensor_prox sensor_rate_limit block_wifi_scan block_notif_listen hide_notif_perm mic_block audio_fp_block cam_null disable_passive_loc block_mediastore; do
  grep -Fq "$legacy_key" "$LEGACY_HOOK" || fail "legacy duplicate ownership references unknown key: $legacy_key"
done
# Keep the native publisher's per-feature ownership mapping in lockstep with
# the legacy fail-closed set injected by merge_hook_single_apk.py.
for mapping in \
  '{"exif_strip","exif_strip"}' \
  '{"clipboard_read_block","clipboard"}' \
  '{"clipboard_isolate","clipboard_isolate"}' \
  '{"sensor_accel","sensor_accel"}' \
  '{"sensor_gyro","sensor_gyro"}' \
  '{"sensor_light","sensor_light"}' \
  '{"sensor_magnet","sensor_magnet"}' \
  '{"sensor_pressure","sensor_pressure"}' \
  '{"sensor_prox","sensor_prox"}' \
  '{"sensor_rate_limit","sensor_rate_limit"}' \
  '{"wifi_scan_block","block_wifi_scan"}' \
  '{"notification_listen_block","block_notif_listen"}' \
  '{"notification_permission_hide","hide_notif_perm"}' \
  '{"mic_access_block","mic_block"}' \
  '{"mic_silence","mic_block"}' \
  '{"mic_silence","audio_fp_block"}' \
  '{"camera_access_block","cam_null"}' \
  '{"location_access_block","disable_passive_loc"}' \
  '{"media_store_query_block","block_mediastore"}'; do
  grep -Fq "$mapping" "$ACTIVITY" || fail "native publisher/legacy ownership mapping drifted: $mapping"
done
for owned_key in exif_strip clipboard clipboard_isolate sensor_accel sensor_gyro sensor_light sensor_magnet sensor_pressure sensor_prox sensor_rate_limit block_wifi_scan block_notif_listen hide_notif_perm mic_block audio_fp_block cam_null disable_passive_loc block_mediastore; do
  grep -Fq "\"$owned_key\"" "$MERGE_HOOK" || fail "fail-closed legacy ownership set is missing: $owned_key"
done
grep -Fq 'if (!api101OwnershipAvailable && API101_OWNED_LEGACY_KEYS.contains(k)) return false;' "$MERGE_HOOK" || fail "unreadable ownership map must disable migrated legacy overlap hooks"
grep -Fq '.append("privacy_enabled=").append(anyPrivacy?' "$ACTIVITY" || fail "privacy feature master flag is not serialized"
grep -Fq '.append("wifi_scan_enabled=").append(anyWifi?' "$ACTIVITY" || fail "Wi-Fi scan feature master flag is not serialized"
grep -Fq '.append("notification_listen_enabled=").append(anyNotif?' "$ACTIVITY" || fail "notification listener feature master flag is not serialized"
grep -Fq '.append("notification_permission_hide_enabled=").append(anyNotifPerm?' "$ACTIVITY" || fail "notification permission feature master flag is not serialized"
grep -Fq '.append("clipboard_isolate_enabled=").append(anyClipboardIso?' "$ACTIVITY" || fail "clipboard isolation master flag is not serialized"
! grep -Fq '{"privacy","spoof_android_id"}' "$ACTIVITY" || fail "generic privacy master must not suppress the legacy Android-ID key"
! grep -Eq 'member_diag|memberDiag|installMember|billing|purchase' "$LEGACY_HOOK" || fail "read-only member diagnostics must not be duplicated by the legacy Hook entrypoint"
grep -Fq 'installDynamicMemberClassDiscovery' "$HOOK" || fail "read-only member diagnostics must remain owned by the API-101 Hook runtime"
grep -Fq 'OBSERVE|0' "$ACTIVITY" || fail "native custom Hook UI must create observe-only rules"
grep -Fq 'dev_hook_enabled=1' "$ACTIVITY" || fail "custom Hook publisher must serialize explicit per-app opt-in"
grep -Fq 'append(",dev_rule_")' "$ACTIVITY" || fail "custom Hook publisher must serialize each custom rule into Remote Files"
grep -Fq 'effectiveDeveloperRules = DeveloperHookRule.selectEffective(target.developerRules)' "$HOOK" || fail "custom Hook runtime must resolve priority once before interception"
grep -Fq 'for (DeveloperHookRule rule : effectiveDeveloperRules)' "$HOOK" || fail "custom Hook runtime must iterate only the shared priority-resolved rules"
! grep -Fq 'for (DeveloperHookRule rule : target.developerRules)' "$HOOK" || fail "custom Hook runtime must not bypass priority resolution with raw rule iteration"
grep -Fq 'rule.action == DeveloperHookRule.Action.OBSERVE' "$HOOK" || fail "custom Hook runtime must install only read-only observation rules"
! grep -Fq 'RETURN_TRUE' "$ACTIVITY" || fail "native custom Hook UI must not expose return-value replacement"
! grep -Fq 'RETURN_FALSE' "$ACTIVITY" || fail "native custom Hook UI must not expose return-value replacement"
grep -Fq 'MemberTestGate.isEnabled' "$HOOK" || fail "debug-only developer test fixtures must remain behind explicit debug/opt-in gate"
grep -Fq '仅对可调试版本目标应用生效' "$ACTIVITY" || fail "native Hook UI must explain the debuggable target requirement"
grep -Fq '目标应用：可调试版本' "$ACTIVITY" || fail "selected target UI must report when custom Hook can execute"
grep -Fq '目标应用：非调试版本' "$ACTIVITY" || fail "selected target UI must report when custom Hook is inactive"
grep -Fq 'fx-api101-managed.conf' "$ACTIVITY" || fail "native Hook publisher does not publish legacy duplicate-suppression map"
grep -Fq 'fx-native-hook-targets-' "$ACTIVITY" || fail "native Hook config must persist across module apply/boot"
grep -Fq 'nativeOverlayTemp' "$ACTIVITY" || fail "native Hook overlay must be staged before atomic publish"
[ -s "$GENERATOR" ] || fail "module Remote Files generator missing"
grep -Fq 'fx-native-hook-targets-$_gxc_uid.conf' "$GENERATOR" || fail "module apply would overwrite the native Hook config"
grep -Fq 'native Hook overlay invalid' "$GENERATOR" || fail "module generator must reject invalid native overlay instead of silently replacing it"
grep -Fq 'patch_native_hook_config_overlay.py' "$ROOT/.github/workflows/build-fx-adhook.yml" || fail "APP validation workflow must stage native Hook overlay support"
grep -Fq 'patch_native_hook_config_overlay.py' "$ROOT/.github/workflows/build-fx-kernelsu.yml" || fail "KernelSU package workflow must stage native Hook overlay support"
grep -Fq 'chcon u:object_r:magisk_file:s0' "$ACTIVITY" || fail "LSPosed Remote Files must receive the framework SELinux label"
grep -Fq 'chmod 0755 ' "$ACTIVITY" || fail "LSPosed Remote Files directory must retain framework-compatible permissions"
grep -Fq 'androidUser=android.os.Process.myUid()/100000' "$ACTIVITY" || fail "Remote Files path must use the current Android user ID"
grep -Fq 'listRemoteFiles()).contains(CONFIG_NAME)' "$HOOK" || fail "runtime must verify config presence before opening Remote Files"
grep -Fq 'Remote Files config is missing:' "$HOOK" || fail "missing Remote Files config must produce an explicit diagnostic"
grep -Fq 'chcon u:object_r:shell_data_file:s0' "$ACTIVITY" || fail "legacy ownership map must receive the legacy config SELinux label"
! grep -Fq 'privacyEnabled = false;' "$MERGE_HOOK" || fail "merge script must not disable API-101 per-app privacy runtime"
[ -s "$HOOK" ] || fail "unified Ad Hook runtime missing"
[ -s "$PARSER" ] || fail "unified Hook config parser missing"
[ -s "$PARSER_TEST" ] || fail "unified Hook parser regression tests missing"
grep -Fq 'acceptsEmptyTargetsForAutomaticAdOnlyConfiguration' "$PARSER_TEST" || fail "automatic Ad-only config must allow an empty optional target list"
grep -Fq 'if (!schemaSeen || !adsSeen || !privacySeen || !sectionSeen)' "$PARSER" || fail "schema validation must not require any non-empty target rows"
grep -Fq "AUTO_AD_TARGET" "$HOOK" || fail "built-in automatic Ad target missing"
grep -Fq "final boolean adsForPackage = adsEnabled;" "$HOOK" || fail "Ad runtime still depends on per-app category switches"
grep -Fq "adsEnabled = true;" "$HOOK" || fail "legacy Ad master switch still controls automatic recognition"
! grep -Fq "if (!configLoaded) return;" "$HOOK" || fail "automatic Ad detection is incorrectly gated on Remote Files config"
! grep -Fq "if (!remoteFilesAvailable) {" "$HOOK" || fail "automatic Ad detection must not stop when LSPosed Remote Files capability is unavailable"
grep -Fq "automatic Ad detection enabled; optional remote per-app policies unavailable" "$HOOK" || fail "Ad detection must remain active when optional Remote Files are unavailable"
grep -Fq "return AUTO_AD_TARGET;" "$HOOK" || fail "Ad runtime still requires an explicit target list"
for protected_pkg in com.android.systemui com.android.settings com.android.permissioncontroller com.google.android.permissioncontroller com.android.phone com.android.server.telecom com.android.networkstack com.android.bluetooth com.android.nfc com.google.android.gms com.android.vending; do
  grep -Fq "\"$protected_pkg\"" "$HOOK" || fail "automatic Ad hooks must protect Android core process: $protected_pkg"
done
grep -Fq 'return enabled > 0;' "$HOOK" || fail "automatic Ad classifier must match generic strong markers when all categories are enabled"
grep -Fq 'rule.action == DeveloperHookRule.Action.OBSERVE' "$HOOK" || fail "custom Hook rules must be restricted to read-only observation"
grep -Fq 'installDeveloperObservationHook(param.getClassLoader(), pkg' "$HOOK" || fail "custom Hook observation rules are parsed but never installed"
grep -Fq 'target.developerHooksEnabled && debuggableTarget' "$HOOK" || fail "custom Hook must require explicit per-app opt-in and a debuggable target build"
grep -Fq 'developerObserveForPackage = true;' "$HOOK" || fail "custom Hook observation opt-in is never enabled for a valid target"
grep -Fq 'DeveloperHookRule.selectEffective(target.developerRules)' "$HOOK" || fail "custom Hook runtime must honor configured rule priority and disabled-rule semantics"
grep -Fq "scanAddedViewTree(added, target, pkg);" "$HOOK" || fail "dynamic inserted Ad containers must be recursively scanned"
grep -Fq 'MAX_DYNAMIC_AD_SCAN_NODES = 400' "$HOOK" || fail "dynamic Ad scans must have a per-insertion node budget"
grep -Fq 'MAX_DYNAMIC_AD_SCAN_DEPTH = 12' "$HOOK" || fail "dynamic Ad scans must have a recursion depth budget"
grep -Fq 'scanDynamicTree(child, added, 1, visited, target, pkg)' "$HOOK" || fail "dynamic insertion must use the bounded scanner"
grep -Fq 'count[0]++ >= MAX_DYNAMIC_AD_SCAN_NODES' "$HOOK" || fail "dynamic scanner must stop at its node budget"
grep -Fq 'hiddenAdViews' "$HOOK" || fail "hidden Ad views must retain their original visibility for restoration"
grep -Fq 'installVisibilityMutationObserver' "$HOOK" || fail "Ad visibility changes must be observed before restoring hidden views"
grep -Fq 'if (!visibilityMutationObserverInstalled)' "$HOOK" || fail "automatic Ad View hiding must fail open when visibility ownership cannot be tracked"
grep -Fq 'automatic View hiding disabled for safety' "$HOOK" || fail "observer failure must be reported as a safe degradation"
grep -Fq 'externallyChangedAdViews.put(changed, Boolean.TRUE)' "$HOOK" || fail "target-app visibility mutations must be distinguished from FX mutations"
grep -Fq 'fxVisibilityMutation.set(true)' "$HOOK" || fail "FX-owned visibility writes must be excluded from external mutation tracking"
grep -Fq '!changedByTarget && view.getVisibility() == View.GONE' "$HOOK" || fail "restore must not overwrite target-app visibility changes"
grep -Fq 'view.addOnAttachStateChangeListener(listener)' "$HOOK" || fail "hidden Ad views must restore when detached and reused"
grep -Fq 'restoreHiddenAdView(detached);' "$HOOK" || fail "Ad view detach callback must restore original visibility"
grep -Fq 'restoreHiddenAdView(view);' "$HOOK" || fail "views no longer matching Ad rules must be restored during rescans"
! grep -Fq 'scanTree(child, added, 1, visited, target, pkg)' "$HOOK" || fail "dynamic insertion must not use the larger activity scanner"
grep -Fq "lastAddedViewScan" "$HOOK" || fail "duplicate addView callbacks must be deduplicated"
grep -Fq "now - prior < 300L" "$HOOK" || fail "dynamic Ad scan deduplication window is missing"
! grep -Eq 'toggle\("(启动页广告|信息流广告|弹窗 / 插屏广告)"' "$ACTIVITY" || fail "legacy per-app Ad switches must be removed from Hook UI"
grep -Fq '.append("ads_enabled=1\n")' "$ACTIVITY" || fail "published Hook config must not disable built-in Ad recognition"
grep -Fq 'cp -p' "$ACTIVITY" || fail "Remote Files publishing must retain a rollback backup"
grep -Fq 'sha256sum' "$ACTIVITY" || fail "Remote Files publishing must verify the written config hash"
grep -Fq 'actual_tmp' "$ACTIVITY" || fail "Remote Files temp file hash must be checked before publish"
grep -Fq 'actual=$(sha256sum' "$ACTIVITY" || fail "Remote Files final hash must be recomputed"
grep -Fq 'actual_managed=$(sha256sum' "$ACTIVITY" || fail "legacy ownership map final hash must be recomputed"
grep -Fq 'getSharedPreferences("fx_hook_publish", MODE_PRIVATE)' "$ACTIVITY" || fail "verified Hook publish state must persist across UI navigation"
grep -Fq '.putString("sha256", expectedHash)' "$ACTIVITY" || fail "successful Hook publish must persist the verified config hash"
grep -Fq '.putLong("published_at", System.currentTimeMillis())' "$ACTIVITY" || fail "successful Hook publish must persist its timestamp"
grep -Fq 'Remote Files：' "$ACTIVITY" || fail "Hook hub must show the last published Remote Files path"
grep -Fq '不证明 LSPosed 作用域、热加载或目标进程注入状态' "$ACTIVITY" || fail "publish status must not overclaim framework activation"
grep -Fq 'managedHash' "$ACTIVITY" || fail "legacy ownership map expected hash is missing"
grep -Fq 'configBytes.length>65536' "$ACTIVITY" || fail "Hook Remote Files config must enforce the parser byte limit"
grep -Fq 'rows.size()>990' "$ACTIVITY" || fail "native Hook overlay must respect the generator line-count limit"
grep -Fq 'managedBytes.length>65536' "$ACTIVITY" || fail "legacy ownership map must be bounded"
grep -Fq 'command.length()>131072' "$ACTIVITY" || fail "Root publisher must enforce the command bridge limit"
grep -Fq 'sync;' "$ACTIVITY" || fail "Remote Files publish must flush before and after atomic rename"
grep -Fq "adDetection=automatic(splash/feed/overlay)" "$HOOK" || fail "automatic Ad classifier is not reported by runtime"
grep -q 'WebViewAssetLoader' "$ACTIVITY" || fail "secure app asset loader missing"
grep -Fq 'new WebViewAssetLoader.AssetsPathHandler(MainActivity.this)' "$ACTIVITY" || fail "WebView asset fallback must receive an Android Context"
! grep -Fq 'new WebViewAssetLoader.AssetsPathHandler(getAssets())' "$ACTIVITY" || fail "AssetManager is not a supported AssetsPathHandler constructor argument"
grep -q 'appassets.androidplatform.net/assets/webroot/index.html' "$ACTIVITY" || fail "WebUI is not loaded from app-owned assets"
grep -q 'setAllowFileAccess(false)' "$ACTIVITY" || fail "WebView file access must remain disabled"
grep -q 'setAllowUniversalAccessFromFileURLs(false)' "$ACTIVITY" || fail "universal file URL access must remain disabled"
grep -q 'window.ksu={exec:function' "$ACTIVITY" || fail "KernelSU WebUI compatibility bridge missing"
grep -q 'window.showSaveFilePicker' "$ACTIVITY" || fail "native export bridge shim missing"
grep -q 'onShowFileChooser' "$ACTIVITY" || fail "native import file picker missing"
grep -q 'openHookManager' "$BRIDGE" || fail "native Hook manager entry missing"
grep -q 'FXRoot.exec' "$ACTIVITY" || fail "WebUI root execution shim missing"
grep -q 'CALLBACK' "$BRIDGE" || fail "callback name validation missing"
grep -Fq 'new ArrayBlockingQueue<>(8)' "$BRIDGE" || fail "Root WebUI bridge must bound queued privileged commands"
grep -Fq 'new ThreadPoolExecutor(' "$BRIDGE" || fail "Root WebUI bridge executor missing"
grep -Fq '2, 2, 0L, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(8)' "$BRIDGE" || fail "Root WebUI bridge must cap concurrency at two processes and eight queued commands"
grep -Fq 'RejectedExecutionException' "$BRIDGE" || fail "Root WebUI bridge must report overload instead of spawning unbounded threads"
grep -Fq '队列已满' "$BRIDGE" || fail "Root WebUI bridge must return a clear overload error"
grep -q '@JavascriptInterface' "$BRIDGE" || fail "JavaScript bridge annotation missing"
grep -q 'saveBase64' "$BRIDGE" || fail "Android Downloads export bridge missing"
grep -Fq 'private volatile boolean closed;' "$BRIDGE" || fail "RootBridge lifecycle closed state missing"
grep -Fq 'public void close() {' "$BRIDGE" || fail "RootBridge close lifecycle method missing"
grep -Fq 'activeRootTasks' "$BRIDGE" || fail "RootBridge must track active privileged commands per WebView bridge"
grep -Fq 'task.cancel(true)' "$BRIDGE" || fail "closing RootBridge must interrupt active privileged commands"
grep -Fq 'extends FutureTask<Void>' "$BRIDGE" || fail "RootBridge active command tracking must use cancellable tasks"
grep -Fq 'synchronized (taskLock)' "$BRIDGE" || fail "RootBridge submission and close must be serialized"
grep -Fq 'if (closed) return;' "$BRIDGE" || fail "closed RootBridge must reject new privileged commands"
grep -Fq 'if (closed || activity.isFinishing()' "$BRIDGE" || fail "RootBridge must suppress callbacks after Activity teardown"
grep -Fq '!closed && !activity.isFinishing()' "$BRIDGE" || fail "queued WebView callbacks must re-check Activity lifecycle"
grep -Fq 'bytes.length > 10 * 1024 * 1024' "$BRIDGE" || fail "export bridge must enforce the decoded 10 MiB byte limit"
grep -Fq 'rootBridge.close();' "$ACTIVITY" || fail "MainActivity must close RootBridge during destruction"
grep -Fq 'private volatile Thread hookPublisherThread;' "$ACTIVITY" || fail "Hook publisher worker must be tracked for Activity teardown"
grep -Fq 'if (hookPublisherThread != null && hookPublisherThread.isAlive())' "$ACTIVITY" || fail "concurrent Hook config publication must be rejected"
grep -Fq 'publisher.interrupt();' "$ACTIVITY" || fail "Activity teardown must cancel an active Hook config publisher"
grep -Eq "chmod 0755 .*legacyDir" "$ACTIVITY" || fail "API-101 ownership map parent directory must be traversable by target app processes"
grep -Eq "! chmod 0755 .*legacyDir" "$ACTIVITY" || fail "API-101 ownership map directory permissions must be verified before publish succeeds"
grep -Fq 'API101_MANAGED_PATH = "/data/local/tmp/privacyguard/fx-api101-managed.conf"' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "legacy Hook ownership map path must match the native publisher"
grep -Fq 'api101OwnershipAvailable = false;' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "legacy Hook ownership map must default to unavailable"
grep -Fq 'if (!managed.isFile() || !managed.canRead())' "$ROOT/fx-patches/merge_hook_single_apk.py" || fail "legacy Hook ownership map must verify target-process readability"
